// ============================================================
// NODE NAMES
// ============================================================

const SKU1_NODE = "Search SKU 1";
const SKU2_NODE = "Search SKU 2";
const BRAND_NODE = "Breville Brand";
const LOOP_NODE = "Loop Over Items2";


// ============================================================
// HELPERS
// ============================================================

function getNodeItems(nodeName) {
  try {
    return $items(nodeName);
  } catch (error) {
    return [];
  }
}


function cleanText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value).trim();
}


function isError(item) {
  if (!item || !item.json) {
    return true;
  }

  const data = item.json;

  return Boolean(
    data.error ||
    data.errorMessage ||
    data.errorDescription ||
    (data.statusCode && Number(data.statusCode) >= 400) ||
    (data.code && String(data.code).startsWith("ERR_"))
  );
}


// ============================================================
// GET DATA
// ============================================================

const sku1Items = getNodeItems(SKU1_NODE);
const sku2Items = getNodeItems(SKU2_NODE);
const brandItems = getNodeItems(BRAND_NODE);


// ============================================================
// GET ROW NUMBER + SKUs FOR *THIS* LOOP ITERATION
// ============================================================

// IMPORTANT: We reference Loop Over Items2 by name using .item
// (paired-item lookup), NOT $items() across all 8 rows.
// .item follows the exact connection path back to the single
// row that triggered THIS specific iteration. This is what
// makes row_number, SKU 1, and SKU 2 correct per-iteration
// instead of always resolving to the first sheet row.

let rowNumber = null;
let sku1 = "";
let sku2 = "";

try {
  const loopItem = $(LOOP_NODE).item.json;

  rowNumber = loopItem.row_number ?? null;
  sku1 = cleanText(loopItem["SKU 1"]);
  sku2 = cleanText(loopItem["SKU 2"]);
} catch (error) {
  // If pairing fails for any reason, leave defaults
  // (null/"") rather than silently grabbing the wrong row.
}


// ============================================================
// EBAY TITLES
// ============================================================

const ebayTitles = [];


function addTitle(title) {

  title = cleanText(title);

  if (!title) {
    return;
  }


  // Don't add obvious error messages
  const lowerTitle = title.toLowerCase();

  if (
    lowerTitle.includes("axioserror") ||
    lowerTitle.includes("404 -") ||
    lowerTitle.includes("request failed")
  ) {
    return;
  }


  // Remove duplicate titles case-insensitively
  const exists = ebayTitles.some(
    existing =>
      existing.toLowerCase() === lowerTitle
  );

  if (!exists) {
    ebayTitles.push(title);
  }
}


function extractEbayTitles(items) {

  for (const item of items) {

    if (isError(item)) {
      continue;
    }

    const data = item.json;


    // --------------------------------------------------------
    // Direct title
    // --------------------------------------------------------

    if (data.title) {
      addTitle(data.title);
    }


    // --------------------------------------------------------
    // eBay Browse API itemSummaries
    // --------------------------------------------------------

    if (Array.isArray(data.itemSummaries)) {

      for (const product of data.itemSummaries) {

        if (
          product &&
          product.title
        ) {
          addTitle(product.title);
        }
      }
    }
  }
}


// ============================================================
// EXTRACT EBAY DATA
// ============================================================

// Search SKU 1
extractEbayTitles(sku1Items);

// Search SKU 2
extractEbayTitles(sku2Items);


// ============================================================
// BREVILLE BRAND DATA
// ============================================================

let brandTitle = "";
let brandDetails = "";
let worksWith = [];


// ============================================================
// RECURSIVELY FIND A FIELD
// ============================================================

function findField(obj, possibleNames) {

  if (!obj || typeof obj !== "object") {
    return null;
  }


  // ----------------------------------------------------------
  // Array
  // ----------------------------------------------------------

  if (Array.isArray(obj)) {

    for (const value of obj) {

      const result = findField(
        value,
        possibleNames
      );

      if (
        result !== null &&
        result !== undefined
      ) {
        return result;
      }
    }

    return null;
  }


  // ----------------------------------------------------------
  // Object
  // ----------------------------------------------------------

  for (const [key, value] of Object.entries(obj)) {

    const normalizedKey = key
      .toLowerCase()
      .replace(/[\s_-]/g, "");


    // Exact normalized field match
    if (
      possibleNames.includes(
        normalizedKey
      )
    ) {
      return value;
    }


    // Search nested objects
    if (
      value &&
      typeof value === "object"
    ) {

      const result = findField(
        value,
        possibleNames
      );

      if (
        result !== null &&
        result !== undefined
      ) {
        return result;
      }
    }
  }

  return null;
}


// ============================================================
// PROCESS BREVILLE RESPONSE
// ============================================================

for (const item of brandItems) {

  if (isError(item)) {
    continue;
  }

  const data = item.json;


  // ----------------------------------------------------------
  // TITLE
  // ----------------------------------------------------------

  if (!brandTitle) {

    const value = findField(
      data,
      [
        "title",
        "producttitle",
        "productname",
        "name"
      ]
    );

    if (typeof value === "string") {

      brandTitle = cleanText(value);
    }
  }


  // ----------------------------------------------------------
  // DETAILS
  // ----------------------------------------------------------

  if (!brandDetails) {

    const value = findField(
      data,
      [
        "details",
        "description",
        "productdescription",
        "shortdescription"
      ]
    );

    if (typeof value === "string") {

      brandDetails = cleanText(value);
    }
  }


  // ----------------------------------------------------------
  // WORKS WITH
  // ----------------------------------------------------------

  const value = findField(
    data,
    [
      "workswith",
      "compatiblewith",
      "compatibility",
      "compatibleproducts",
      "compatiblemodels"
    ]
  );


  if (value) {

    // --------------------------------------------------------
    // Array
    // --------------------------------------------------------

    if (Array.isArray(value)) {

      for (const entry of value) {

        // String entry
        if (
          typeof entry === "string" &&
          entry.trim()
        ) {

          worksWith.push(
            entry.trim()
          );
        }


        // Object entry
        else if (
          entry &&
          typeof entry === "object"
        ) {

          const text = Object.values(entry)
            .filter(
              v =>
                typeof v === "string" ||
                typeof v === "number"
            )
            .map(
              v =>
                String(v).trim()
            )
            .filter(Boolean)
            .join(" — ");


          if (text) {
            worksWith.push(text);
          }
        }
      }
    }


    // --------------------------------------------------------
    // String
    // --------------------------------------------------------

    else if (
      typeof value === "string"
    ) {

      worksWith.push(
        value.trim()
      );
    }
  }
}


// ============================================================
// REMOVE DUPLICATE WORKS WITH
// ============================================================

worksWith = [
  ...new Set(
    worksWith
      .map(
        value =>
          value.trim()
      )
      .filter(Boolean)
  )
];


// ============================================================
// CHECK RESULTS
// ============================================================

const hasEbayResults =
  ebayTitles.length > 0;


const hasBrandResults =
  Boolean(brandTitle) ||
  Boolean(brandDetails) ||
  worksWith.length > 0;


// ============================================================
// EVERYTHING FAILED
// ============================================================

if (
  !hasEbayResults &&
  !hasBrandResults
) {

  const output = {
    row_number: rowNumber
  };


  // Return SKU 1 if available
  if (sku1) {
    output["SKU 1"] = sku1;
  }


  // Return SKU 2 if available
  if (sku2) {
    output["SKU 2"] = sku2;
  }


  output.result = "No results";


  return [
    {
      json: output
    }
  ];
}


// ============================================================
// FINAL OUTPUT
// ============================================================

const output = {
  row_number: rowNumber
};


// ============================================================
// SKU 1
// ============================================================

if (sku1) {
  output["SKU 1"] = sku1;
}


// ============================================================
// SKU 2
// ============================================================

if (sku2) {
  output["SKU 2"] = sku2;
}


// ============================================================
// EBAY TITLES
// ============================================================

if (hasEbayResults) {

  output.ebay_titles = ebayTitles
    .map(
      (title, index) =>
        `${index + 1}. ${title}`
    )
    .join("\n");

} else {

  output.ebay_result = "No output";
}


// ============================================================
// BREVILLE TITLE
// ============================================================

if (brandTitle) {

  output.brand_title =
    brandTitle;
}


// ============================================================
// BREVILLE DETAILS
// ============================================================

if (brandDetails) {

  output.brand_details =
    brandDetails;
}


// ============================================================
// BREVILLE WORKS WITH
// ============================================================

if (worksWith.length > 0) {

  output.works_with = worksWith
    .map(
      (value, index) =>
        `${index + 1}. ${value}`
    )
    .join("\n");
}


// ============================================================
// BREVILLE COMPLETELY FAILED
// ============================================================

if (!hasBrandResults) {

  output.brand_result =
    "No output";
}


// ============================================================
// RETURN
// ============================================================

return [
  {
    json: output
  }
];

