// ============================================================
// GET LLM TITLE
// ============================================================
const title = String($json.text || "").trim();

// ============================================================
// GET ROW NUMBER AND ORIGINAL DATA FROM THE PREVIOUS CODE NODE
// ============================================================
// .item (not .first()) follows the paired-item chain back to
// the exact row this loop iteration started from.
const source = $('Code in JavaScript').item.json;

const rowNumber = source.row_number;

// ============================================================
// GET ORIGINAL DATA
// ============================================================
const sku1 = source["SKU 1"] || "";
const sku2 = source["SKU 2"] || "";
const ebayTitles = source.ebay_titles || "";
const brandResult = source.brand_result || "";

// ============================================================
// CHARACTER COUNT
// ============================================================
const characterCount = title.length;

// ============================================================
// VALIDATION
// ============================================================
const titleValid = characterCount <= 80;

// ============================================================
// OUTPUT
// ============================================================
return [
  {
    json: {
      row_number: rowNumber,
      "SKU 1": sku1,
      "SKU 2": sku2,
      ebay_titles: ebayTitles,
      brand_result: brandResult,
      text: title,
      final_title: title,
      character_count: characterCount,
      title_valid: titleValid,
      needs_retry: !titleValid
    }
  }
];
